2.9c-27-15.4-54.1-30.8-81-46.3c-2.1-1.2-5.3-5.2-5.1-5.4c2.8-3.3,5.4-0.2,7.6,1.2c27.6,17,55.2,34.1,82.7,51.3c0.6,0.4,1.2,0.9,1.7,1.4C111.6,103.3,111.5,103.6,111.3,103.9z\"\n            ></path>\n          </svg>\n\n          <!-- images -->\n          <span\n            class=\"d-inline-block ratio ratio-1x1 rounded-circle bg-cover mx-1 z-index-0\"\n            style=\"\n              max-width: 500px;\n              background-image: url(/public/assets/demo.files/home_1.png);\n            \"\n          ></span>\n          <div class=\"position-absolute bottom-0 w-100 z-index-1\">\n            <span\n              class=\"d-inline-block ratio ratio-1x1 rounded-circle bg-cover mx-1 mb-n5 shadow-lg\"\n              data-jarallax-element=\"-30\"\n              style=\"\n                max-width: 200px;\n                background-image: url(/public/assets/demo.files/home_2.png);\n              \"\n            ></span>\n            <span\n              class=\"d-inline-block ratio ratio-1x1 rounded-circle bg-cover mx-1 mt-n5\"\n              data-jarallax-element=\"-60\"\n              style=\"\n                max-width: 100px;\n                background-image: url(/public/sys/eggjs.svg);\n              \"\n            ></span>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  \n</div>\n\n<!-- sticky quick nav -->\n<div class=\"sticky-top text-center bg-white shadow-primary-xs mt-n2\">\n  <ul id=\"demos-scrollspy\" class=\"list-inline mb-0 py-3 fw-medium\">\n    <li class=\"list-inline-item\">\n      <a href=\"#blog\" class=\"scroll-to d-block py-2 link-normal\">博客</a>\n    </li>\n    <li class=\"list-inline-item\">\n      <span class=\"py-2 px-2 text-gray-300\">&bull;</span>\n    </li>\n    <li class=\"list-inline-item\">\n      <a href=\"#template\" class=\"scroll-to d-block py-2 link-normal\">模板</a>\n    </li>\n    <li class=\"list-inline-item\">\n      <span class=\"py-2 px-2 text-gray-300\">&bull;</span>\n    </li>\n    <li class=\"list-inline-item\">\n      <a href=\"#application\" class=\"scroll-to d-block py-2 link-normal\">应用</a>\n    </li>\n    <li class=\"list-inline-item\">\n      <span class=\"py-2 px-2 text-gray-300\">&bull;</span>\n    </li>\n    <li class=\"list-inline-item\">\n      <a href=\"#download\" class=\"scroll-to d-block py-2 link-normal\">下载</a>\n    </li>\n    <li class=\"list-inline-item\">\n      <span class=\"py-2 px-2 text-gray-300\">&bull;</span>\n    </li>\n    <li class=\"list-inline-item\">\n      <a href=\"#bbs\" class=\"scroll-to d-block py-2 link-normal\">社区</a>\n    </li>\n  </ul>\n</div>\n\n<!-- block : landing pages -->\n\n<div id=\"blog\" class=\"section bg-light p-0\">\n  {% set blog = \'cms_classify\'|@findOne({\n    where:{name:\'blog\'} \n   })%}\n  <div class=\"container\">\n    <div class=\"d-inline-block mx-auto\">\n      <a class=\"fw-bold d-block mt-3 small\" href=\"/cms/list/{{template.name or template.id}}\">Blog <i class=\"fi fi-arrow-right-slim small\"></i></a>\n      <small class=\"fw-bold mt-3 d-block\">Blog</small>\n      <h2 class=\"display-7 mb-3 fw-bold\">博客</h2>\n    </div> \n    \n    {% set top = \'cms_doc\'|@findOne({\n    include : \'cms_classify\',\n    where:{classify_id:blog.id,FIND_IN_SET:[\'position\',4]},\n    order:[[\'id\',\'desc\']]\n    })%}\n    <!-- sticky article -->\n    <div class=\"row\">\n        <a href=\"/cms/detail/{{top.id}}\" target=\"_blank\" class=\"col-12 col-md-4 mb-4\">\n            <img class=\"img-fluid w-100 rounded\"\n                src=\"{{top.cover_url}}\"\n                alt=\"...\">\n        </a>\n\n        <div class=\"col pb-4\">\n\n            <!-- title -->\n            <div class=\"mb-4\">\n\n                <h2 class=\"h4 mb-0\">\n                    <a href=\"/cms/detail/{{top.id}}\" class=\"text-dark fw-medium\">\n                        {{top.title}}\n                    </a>\n                </h2>\n\n                <!-- publish date -->\n                <span class=\"text-muted\">\n                    {{helper.moment(top.createdAt).fromNow()}}\n                </span>\n\n            </div>\n\n            <!-- content preview -->\n            <div class=\"mb-4\">\n                <p>{{top.description|truncate(140, true, \"...\")}}</p>\n            </div>\n\n            <a href=\"/cms/list/{{top.cms_classify.name or top.cms_classify.id}}\" target=\"_blank\" class=\"link-muted\">{{top.cms_classify.title}}</a>\n\n        </div>\n\n    </div>\n    <!-- /sticky article -->\n    <!-- more articles / blog -->\n    <div class=\"pt-1\">\n\n        <div class=\"row\">\n            {% set newlist = \'cms_doc\'|@findAll({\n                include : \'cms_classify\',\n                where:{\n                classify_id:blog.id,\n                id:{op_ne:top.id} \n                },\n                offset: 0,\n                limit: 4,\n                order:[[\'id\',\'desc\']]\n                })%}\n{% for items in newlist | batch(2) %}\n<div class=\"col-12 col-md-6\">\n     {% for item in items %}\n     <div class=\"d-flex mb-3 text-decoration-none\">\n\n        <!-- image -->\n        <div style=\"width:100px;height:100px\"\n            class=\"text-center bg-light rounded bg-cover lazy\"\n            data-background-image=\"{{item.cover_url}}\">\n        </div>\n\n        <div class=\"col px-3\">\n\n            <h3 class=\"h5 fw-bold\">\n                <a href=\"/cms/detail/{{item.id}}\" target=\"_blank\" class=\"text-dark\">\n                    {{item.title}}\n                </a>\n            </h3>\n\n            <p class=\"small\">\n                <strong>({{helper.moment(item.createdAt).fromNow()}})</strong>  {{item.description|truncate(50, true, \"...\")}}\n            </p>\n\n        </div>\n\n    </div>\n    {% endfor %}\n</div>\n            {% endfor %}\n       \n        </div>\n\n    </div>\n    <!-- /more articles / blog -->\n  </div>\n</div>\n<!-- /block : landing pages -->\n\n<!-- block : ecommerce -->\n<div id=\"template\" class=\"section p-0\">\n  {% set template = \'cms_classify\'|@findOne({\n    where:{name:\'template\'} \n   })%}\n  <div class=\"container\">\n    <div class=\"d-inline-block mx-auto\">\n      <a class=\"fw-bold d-block mt-3 small\" href=\"/cms/list/{{template.name or template.id}}\">Template <i class=\"fi fi-arrow-right-slim small\"></i></a>\n      <h2 class=\"display-7 mb-3 text-center fw-bold\">模板</h2>\n    </div>\n    \n       {% set templatelist = \'cms_doc\'|@findAll({\n        include : \'cms_classify\',\n        where:{\n        classify_id:template.id \n        },\n        offset: 0,\n        limit: 3,\n        order:[[\'id\',\'desc\']]\n        })%}\n    {%if templatelist|length>0%}\n    <div class=\"row g-4 g-lg-5\">\n        {%for item in templatelist%}\n      <div class=\"col-12 col-lg-4 mb-5\" data-aos=\"fade-in\">\n        <h3\n          class=\"h5 mb-3 d-flex align-items-center justify-content-lg-between\"\n        >\n          {{item.title|truncate(16, true, \"...\")}}\n        </h3>\n\n        <a\n          href=\"/cms/detail/{{item.id}}\"\n          target=\"_blank\"\n          class=\"d-block bg-white shadow-md rounded p-2\"\n          aria-label=\"template\"\n        >\n          <div\n            class=\"position-relative rounded overflow-hidden overlay-dark-hover overlay-opacity-3 show-hover-container bg-cover lazy\"\n            data-background-image=\"{{item.cover_url}}\"\n          >\n            <svg viewBox=\"0 0 250 340\"></svg>\n          </div>\n        </a>\n      </div>\n        {%endfor%}\n    </div>\n    {%else%}\n    <div class=\"alert alert-primary mb-5\" role=\"alert\">\n        暂无数据\n    </div>\n    {%endif%}\n  </div>\n</div>\n<!-- /block : ecommerce -->\n\n<!-- block : blog + help center -->\n<div id=\"application\" class=\"section bg-light p-0\">\n    {% set application = \'cms_classify\'|@findOne({\n        where:{name:\'application\'} \n       })%}\n  <div class=\"container\">\n    <div class=\"d-inline-block mx-auto\">\n      <a class=\"fw-bold d-block mt-3 small\" href=\"/cms/list/{{application.name or application.id}}\">Application <i class=\"fi fi-arrow-right-slim small\"></i></a>\n      <h2 class=\"display-7 mb-3 fw-bold\">应用</h2>\n    </div>\n       {% set applicationlist = \'cms_doc\'|@findAll({\n        include : \'cms_classify\',\n        where:{\n        classify_id:application.id \n        },\n        offset: 0,\n        limit: 3,\n        order:[[\'id\',\'desc\']]\n        })%}\n    {%if applicationlist|length>0%}\n    <div class=\"row\">\n        {%for item in applicationlist%}\n        <div class=\"col-12 col-lg-4 mb-3\">\n\n            <div class=\"p-3 rounded shadow-md shadow-3d-hover transition-all-ease-250\">\n\n                <a href=\"/cms/detail/{{item.id}}\" target=\"_blank\">\n                    <figure class=\"mb-4 text-center overflow-hidden rounded-top bg-cover lazy\" data-loaded=\"true\" style=\"background-image: url({{item.cover_url}});\">\n                        <img class=\"w-100\" src=\"data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAxNiA5IiAvPg==\" alt=\"...\"> \n                    </figure>\n                </a>\n\n\n                <h2 class=\"h5\">\n                    <span class=\"text-primary\">\n                        官方\n                    </span>\n\n                    <small class=\"float-end text-muted\">\n                       版本：1.0\n                    </small>\n\n                    <span class=\"h6 d-block text-center text-truncate py-3\">\n                        {{item.title}}\n                    </span>\n                </h2>\n\n                <ul class=\"list-inline text-center text-gray-500 fs-6\">\n                    <li class=\"list-inline-item\">作者：arterli</li>\n                    <li class=\"list-inline-item\">/</li>\n                    <li class=\"list-inline-item\">更新时间：{{helper.moment(item.updateAt).fromNow()}}</li>\n                </ul>\n\n            </div>\n\n        </div>\n        {%endfor%}\n    </div>\n \n    {%else%}\n    <div class=\"alert alert-primary mb-5\" role=\"alert\">\n        暂无数据\n    </div>\n    {%endif%}\n  </div>\n</div>\n<!-- /block : blog + help center -->\n\n<!-- block : portfolio -->\n<div id=\"download\" class=\"section p-0\">\n    {% set download = \'cms_classify\'|@findOne({\n        where:{name:\'download\'} \n       })%}\n     \n  <div class=\"container\">\n    <div class=\"d-inline-block mx-auto\">\n      <a class=\"fw-bold d-block mt-3 small\" href=\"/cms/list/{{download.name or download.id}}\">Download <i class=\"fi fi-arrow-right-slim small\"></i></a>\n      <h2 class=\"display-7 mb-3 fw-bold\">下载</h2>\n    </div>\n    {% set downloadlist = \'cms_doc\'|@findAll({\n        include : \'cms_classify\',\n        where:{\n        classify_id:download.id \n        },\n        offset: 0,\n        limit: 3,\n        order:[[\'id\',\'desc\']]\n        })%}\n    {%if downloadlist|length>0%}\n    <div class=\"row aos-init aos-animate\" data-aos=\"fade-in\" data-aos-delay=\"0\">\n     {%for item in downloadlist%}\n        <div class=\"col-12 col-lg-4 mb-4\">\n\n            <div class=\"card border-0 shadow-primary-xs shadow-primary-md-hover transition-all-ease-250 transition-hover-top h-100 rounded overflow-hidden\">\n\n                <div class=\"clearfix\">\n                    <img class=\"img-fluid\" src=\"{{item.cover_url}}\" alt=\"...\">\n\n                    <!-- bottom waves -->\n                    <svg style=\"margin-top:-50px;\" class=\"mb-3\" width=\"100%\" height=\"50px\" fill=\"#ffffff\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 1000 300\" preserveAspectRatio=\"none\">\n                        <path style=\"opacity:0.15\" d=\"M 1000 299 l 2 -279 c -155 -36 -310 135 -415 164 c -102.64 28.35 -149 -32 -232 -31 c -80 1 -142 53 -229 80 c -65.54 20.34 -101 15 -126 11.61 v 54.39 z\"></path>\n                        <path style=\"opacity:0.3\" d=\"M 1000 286 l 2 -252 c -157 -43 -302 144 -405 178 c -101.11 33.38 -159 -47 -242 -46 c -80 1 -145.09 54.07 -229 87 c -65.21 25.59 -104.07 16.72 -126 10.61 v 22.39 z\"></path>\n                        <path style=\"opacity:1\" d=\"M 1000 300 l 1 -230.29 c -217 -12.71 -300.47 129.15 -404 156.29 c -103 27 -174 -30 -257 -29 c -80 1 -130.09 37.07 -214 70 c -61.23 24 -108 15.61 -126 10.61 v 22.39 z\"></path>\n                    </svg>\n\n                </div>\n\n                <!-- lines, looks like through a glass -->\n                <div class=\"absolute-full w-100 overflow-hidden\">\n                    <img class=\"img-fluid\" width=\"2000\" height=\"2000\" src=\"/public/assets/images/masks/shape-line-lense.svg\" alt=\"...\">\n                </div>\n\n                <div class=\"card-body fw-light mt-0\">\n\n                    <h2 class=\"h5 card-title mb-3\">\n                        {{item.title}}\n                    </h2>\n\n                    <p class=\"fs-6 mb-0\">\n                        {{item.description|truncate(50, true, \"...\")}}\n                    </p>\n\n                </div>\n\n                <div class=\"card-footer bg-transparent border-0\">\n                    <span class=\"float-end fs-6 text-gray-500 p-2\">\n                       官方\n                    </span>\n\n                    <a href=\"/cms/detail/{{item.id}}\" target=\"_blank\" class=\"btn btn-sm btn-primary btn-soft opacity-6\">\n                        下载\n                    </a>\n                </div>\n\n            </div>\n\n        </div>\n{%endfor%}\n    \n    </div>\n    {%else%}\n    <div class=\"alert alert-primary mb-5\" role=\"alert\">\n        暂无数据\n    </div>\n    {%endif%}\n\n  </div>\n</div>\n<!-- /block : portfolio -->\n\n<!-- block : admin -->\n<div id=\"bbs\" class=\"section bg-theme-color-light p-0\">\n  <div class=\"container\">\n    <div class=\"d-inline-block mx-auto\">\n        <a class=\"fw-bold d-block mt-3 small\" href=\"/cms/list/{{application.name or application.id}}\">BBS <i class=\"fi fi-arrow-right-slim small\"></i></a>\n      <h2 class=\"display-7 mb-5 fw-bold\">社区</h2>\n    </div>\n\n    <div class=\"alert alert-primary mb-5\" role=\"alert\">\n        开发中...\n    </div>\n  </div>\n</div>\n<!-- block : admin -->\n<!-- block : icons : 3 -->\n<div\nclass=\"container bg-gray-200 rounded-xl mt-3\"\ndata-aos=\"fade-in\"\ndata-aos-delay=\"200\"\ndata-aos-offset=\"0\"\n>\n<!-- svg lines -->\n<svg\n  class=\"rtl-scalex-n1 position-absolute start-0 top-0 z-index-1 text-warning mx-3 mt-n5\"\n  fill=\"currentColor\"\n  data-aos=\"fade-up\"\n  data-aos-delay=\"200\"\n>\n  <path\n    d=\"M35.2,1.6c37.3,18.9,72.2,41.8,107.4,64.1c-0.2,0.4-0.4,0.8-0.6,1.2c-1.9-0.8-3.9-1.5-5.6-2.5c-30.3-17-60.6-34.1-91-51.1c-4.1-2.3-8.1-4.6-12.2-6.9c-2.3-1.2-2.8-2.7-1-4.7C33.2,1.6,34.2,1.6,35.2,1.6z\"\n  ></path>\n  <path\n    d=\"M137.4,81.7C93.8,56.6,50.2,31.6,6.6,6.5C6.1,6.2,6.1,5.1,5.2,2.5c4.4,1.6,7.6,2.4,10.5,3.9c10,5.3,20,10.6,29.7,16.5c29.9,18.5,59.6,37.2,89.4,55.9c1.1,0.7,2.1,1.5,3.1,2.2C137.7,81.2,137.6,81.5,137.4,81.7z\"\n  ></path>\n  <path\n    d=\"M122.8,88.8C87.6,68.9,52.4,49,17.2,29c-0.6-0.4-0.8-1.6-1.9-4c3.7,1.1,6.3,1.3,8.3,2.5c20.1,11.4,40.3,22.7,60.1,34.5 c12.1,7.2,23.8,15.3,35.6,23.1c1.4,0.9,2.6,1.9,3.9,2.9C123.1,88.3,122.9,88.6,122.8,88.8z\"\n  ></path>\n  <path\n    d=\"M111.3,103.9c-1.8-1-3.7-1.9-5.5-2.9c-27-15.4-54.1-30.8-81-46.3c-2.1-1.2-5.3-5.2-5.1-5.4c2.8-3.3,5.4-0.2,7.6,1.2c27.6,17,55.2,34.1,82.7,51.3c0.6,0.4,1.2,0.9,1.7,1.4C111.6,103.3,111.5,103.6,111.3,103.9z\"\n  ></path>\n</svg>\n\n<div class=\"row col-border text-center overflow-hidden\">\n  <div\n    class=\"col-6 col-md-4 py-4 z-index-1\"\n    data-aos=\"fade-up\"\n    data-aos-delay=\"50\"\n    data-aos-offset=\"0\"\n  >\n    <a\n      href=\"#\"\n      class=\"d-block text-decoration-none text-dark transition-hover-top transition-all-ease-250\"\n    >\n      <div\n        style=\"width: 120px; height: 120px\"\n        class=\"bg-white mb-4 border border-light rounded-circle shadow-md d-inline-flex justify-content-center align-items-center\"\n      >\n        <i class=\"fi fi-brain display-5\"></i>\n      </div>\n\n      <h3 class=\"h4\">高效自然的研发体验</h3>\n\n      <p class=\"max-w-350 mx-auto fs-6\">\n        渐进式开发，学习曲线平滑，提供一站式开发套件，为研发全流程保驾护航。\n      </p>\n    </a>\n  </div>\n\n  <div\n    class=\"col-6 col-md-4 py-4 z-index-1\"\n    data-aos=\"fade-up\"\n    data-aos-delay=\"250\"\n    data-aos-offset=\"0\"\n  >\n    <a\n      href=\"#admin\"\n      class=\"scroll-to d-block text-decoration-none text-dark transition-hover-top transition-all-ease-250\"\n    >\n      <div\n        style=\"width: 120px; height: 120px\"\n        class=\"bg-white mb-4 border border-light rounded-circle shadow-md d-inline-flex justify-content-center align-items-center\"\n      >\n        <i class=\"fi fi-heart-empty display-5\"></i>\n      </div>\n\n      <h3 class=\"h4\">灵活、高扩展性</h3>\n\n      <p class=\"max-w-350 mx-auto fs-6\">\n        约定优于配置，高度灵活的定制性，业界领先的插件机制和上层业务框架机制。\n      </p>\n    </a>\n  </div>\n\n  <div\n    class=\"col-12 col-md-4 py-4 z-index-1 border-top-xs\"\n    data-aos=\"fade-up\"\n    data-aos-delay=\"450\"\n    data-aos-offset=\"0\"\n  >\n    <a\n      href=\"#\"\n      class=\"d-block text-decoration-none text-dark transition-hover-top transition-all-ease-250\"\n    >\n      <div\n        style=\"width: 120px; height: 120px\"\n        class=\"bg-white mb-4 border border-light rounded-circle shadow-md d-inline-flex justify-content-center align-items-center\"\n      >\n        <i class=\"fi fi-layers display-5\"></i>\n      </div>\n\n      <h3 class=\"h4\">完善的生态</h3>\n\n      <p class=\"max-w-350 mx-auto fs-6\">\n        基于开源生态，专为泛蚂蚁生态定制，一分钟接入后端服务中间件，支持多种部署环境。\n      </p>\n    </a>\n  </div>\n</div>\n</div>\n<!-- /block : icons : 3 -->\n{% endblock %}\n',1,1,'4014fd49-b884-4338-ae96-c551567b5553'),(13,'2025-07-30 00:42:42','2025-07-30 00:42:42','37934d72-fe2c-4a0d-afbb-414993e63986','默认列表模板','list','default','{% extends \"./inc_base.html\" %}\n{%block body%}class=\"header-scroll-reveal\"{%endblock%}\n{% block middle %}\n<div class=\"section pt-4 pb-4\">\n    <div class=\"container\">\n        <!--\n\n	Color Schemas\n	.swiper-white (default)\n	.swiper-black\n	.swiper-dark\n	.swiper-primary\n	.swiper-danger\n	.swiper-success\n	.swiper-warning\n	.swiper-info\n	.swiper-pink\n	.swiper-indigo\n	.swiper-purple\n\n	Autoplay\n	\"autoplay\": false\n	\"autoplay\": { \"delay\" : 1500, \"disableOnInteraction\": false }\n\n-->\n        {% set position = \'cms_doc\'|@findAll({\n        include : \'cms_classify\',\n        where:{\n        classify_id:classify.id,\n        FIND_IN_SET:[\'position\',1]\n        },\n        offset: 0,\n        limit: 10\n        })%}\n        {%if position %}\n        <div class=\"swiper-container swiper-purple mb-4 d-none d-lg-block\" data-swiper=\'{\n		\"slidesPerView\": 3,\n		\"spaceBetween\": 8,\n		\"slidesPerGroup\": 1,\n		\"loop\": true,\n		\"autoplay\": { \"delay\" : 3000, \"disableOnInteraction\": false },\n		\"breakpoints\": {\n			\"1024\": { \"slidesPerView\": \"3\" },\n			\"920\":	{ \"slidesPerView\": \"2\" },\n			\"640\":	{ \"slidesPerView\": \"1\" },\n      \"300\":	{ \"slidesPerView\": \"1\" }\n		}\n	}\'>\n\n            <div class=\"hide swiper-wrapper\">\n                {%for item in position%}\n                <div class=\"swiper-slide\">\n                    <div class=\"card\">\n                        <div class=\"row g-0\">\n                            <div class=\"col-md-4\">\n                                {%if not item.cover_url%}\n                                <svg class=\"d-block w-100 rounded-start\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"\n                                    style=\"text-anchor: middle; user-select: none ;height:104px\">\n                                    <rect width=\"100%\" height=\"100%\" fill=\"#c6d3e6\"></rect>\n                                    <text x=\"50%\" y=\"50%\" fill=\"#869ab8\" dy=\".2em\">\n                                        暂无图片\n                                    </text>\n                                </svg>\n                                {%else%}\n                                <img\n                  style=\"height:104px\"\n                    class=\"img-fluid rounded-start\"\n                    src=\"{{item.cover_url}}\"\n                    alt=\"...\"\n                  />\n                  {%endif%}\n                            </div>\n                            <div class=\"col-md-8\">\n                                <div class=\"card-body\">\n                                    <a href=\"/cms/detail/{{item.id}}\" class=\"card-title\"\n                                        target=\"_blank\">{{item.title|truncate(26, true, \"...\")}}</a>\n                                    <p class=\"card-text\">\n                                        <small class=\"text-muted\">{{item.cms_classify.title}}/{{helper.moment(item.createdAt).fromNow()}}</small>\n                                    </p>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                {%endfor%}\n\n\n            </div>\n\n            <!-- Add Arrows -->\n            <div class=\"rounded-circle swiper-button-next\"></div>\n            <div class=\"rounded-circle swiper-button-prev\"></div>\n\n        </div>\n        {%endif%}\n        <div class=\"row\">\n            <div class=\"col-12 col-lg-10 order-2\">\n                <div class=\"shadow-xs bg-white mb-4 p-3 rounded clearfix\">\n                    <label class=\"h5 mb-0\"> {{classify.title}} </label>\n\n                    <div class=\"float-end position-relative mt-1 small\">\n                        排序: &nbsp;\n                        <a href=\"{{ orderby.def.url }}\" class=\"text-danger text-decoration-none\"\n                            data-bs-toggle=\"dropdown\" aria-expanded=\"false\">\n                            {{ orderby.def.name }}\n                            <i class=\"fi fi-arrow-down-slim smaller\"></i>\n                        </a>\n\n                        <ul class=\"dropdown-menu border-0 mt-3 rounded fs-6\">\n                            {% for item in orderby.list %}\n                            <li class=\"dropdown-item {% if ctx.query.orderby==item.id %}active{% endif %}\">\n                                <a href=\"{{ item.url }}\" class=\"text-muted small py-2 d-block\">{{ item.name }}</a>\n                            </li>\n                            {% endfor %}\n                        </ul>\n                    </div>\n                    <hr />\n                    <h1 class=\"h6 mb-0\">\n                        找到 <span class=\"text-danger\">{{ list.count }}</span> 个相关结果\n                    </h1>\n                </div>\n\n                {%for item in list.rows%}\n                <!-- item -->\n                <div class=\"shadow-xs rounded mb-3 p-3\">\n                    <div class=\"row g-0\">\n                        <div class=\"col-12 col-md-3 p--0\">\n                            <figure class=\"overflow-hidden text-center clearfix d-block m-0 position-relative\">\n                                <a href=\"/cms/detail/{{item.id}}\" class=\"text-decoration-none\" target=\"_blank\">\n                                    {%if not item.cover_url%}\n                                    <svg class=\"d-block w-100 fs-1 rounded\" xmlns=\"http://www.w3.org/2000/svg\"\n                                        role=\"img\" style=\"text-anchor: middle; user-select: none\">\n                                        <rect width=\"100%\" height=\"100%\" fill=\"#c6d3e6\"></rect>\n                                        <text x=\"50%\" y=\"50%\" fill=\"#869ab8\" dy=\".3em\">\n                                            暂无图片\n                                        </text>\n                                    </svg>\n                                    {%else%}\n                                    <img\n                    class=\"img-fluid rounded lazy\"\n                    data-src=\"{{item.cover_url}}\"\n                    src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\"\n                    alt=\"...\"\n                  />\n                  {%endif%}\n                                </a>\n                            </figure>\n                        </div>\n                        <div class=\"col-12 mt-3 d-block d-sm-none\">\n                            <!-- mobile spacer -->\n                        </div>\n                        <div class=\"col-12 col-md-9 order-xs-3 order-md-2 order-lg-2 p-0 position-relative\">\n                            {%if item.level>0%}\n                            <span class=\"position-absolute top-0 end-0 mt-1\" data-bs-toggle=\"tooltip\" data-bs-placement=\"top\" title=\"置顶[{{item.level}}]\">\n                <svg width=\"15\" viewBox=\"0 0 512 512\" class=\"fill-danger\"><path d=\"M141.938 324.965l-130.119 159.058c-3.387 4.146-3.517 10.24 0 14.535 4.002 4.918 11.247 5.646 16.147 1.625l159.107-130.131c-8.13-7.24-15.955-14.598-23.244-21.893-7.63-7.626-14.92-15.401-21.891-23.194zM447.89 64.1c-44.49-44.502-94.756-66.346-112.309-48.846-.903.908-92.757 126.197-138.796 188.98-30.166-21.5-57.219-34.082-74.656-34.068-6.374 0-11.485 1.662-14.971 5.18-19.197 19.164 16.646 86.076 80.028 149.459 51.797 51.797 105.971 85.223 134.488 85.223 6.387 0 11.472-1.68 14.971-5.178 13.084-13.084.548-48.41-28.858-89.658 62.802-46.043 188.047-137.893 188.932-138.781 17.535-17.518-4.339-67.804-48.829-112.311z\"></path></svg>\n              </span>\n                            {%endif%}\n                            <div class=\"p-0 p-lg-3\">\n                                <h3 class=\"h5 mb-2\">\n                                    <a href=\"/cms/detail/{{item.id}}\" target=\"_blank\"> {{item.title}} </a>\n                                </h3>\n\n                                <p class=\"mb-2\">\n                                    {{item.description|truncate(80, true, \"...\")}}\n                                </p>\n\n                                <ul class=\"list-inline text-gray-700 small mb-2\">\n                                    <li class=\"list-inline-item\">{{item.pathTitle}}</li>\n                                    <li class=\"list-inline-item\">/</li>\n                                    <li class=\"list-inline-item\">\n                                        {{helper.moment(item.createdAt).fromNow()}}\n                                    </li>\n                                    <li class=\"list-inline-item\">/</li>\n                                    <li class=\"list-inline-item\">{{item.view}}次</li>\n                                </ul>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <!-- /item -->\n                {%endfor%}\n                <!-- pagination -->\n                <nav aria-label=\"pagination\" class=\"mt-4\">{{pagination|safe}}</nav>\n                <!-- pagination -->\n            </div>\n\n            <div class=\"col-12 col-lg-2 mb-3 order-1\">\n                <form method=\"get\" action=\"{{ classify.url }}\" class=\"input-group-over d-block mb-2\">\n                    <div class=\"form-floating mb-3\">\n                        <input\n              placeholder=\"搜索...\"\n              id=\"doc_search\"\n              name=\"keywords\"\n              type=\"text\"\n              class=\"form-control\"\n              value=\"{{ ctx.query.keywords }}\"\n            />\n            {% if ctx.query.sub %}\n                        <input name=\"sub\" type=\"hidden\" value=\"{{ ctx.query.sub }}\" />\n            {% endif %}\n                        <label for=\"doc_search\">搜索...</label>\n                    </div>\n\n                    <button type=\"submit\" class=\"btn smaller\">\n            <i class=\"fi fi-search m-0\"></i>\n          </button>\n                </form>\n                {%set classifyList = classify.id|@classify(\'top\')%} {%if classifyList%}\n                <!-- CATEGORIES -->\n                <nav\n                    class=\"nav-deep nav-deep-light mb-3 shadow-xs shadow-none-md shadow-none-xs px-3 pb-3 p-0-md p-0-xs rounded\">\n                    <!-- mobile trigger : categories -->\n                    <button\n            class=\"clearfix btn btn-toggle btn-sm w-100 text-align-left shadow-md border rounded mb-1 d-block d-lg-none\"\n            data-bs-target=\"#nav_responsive\"\n            data-toggle-container-class=\"d-none d-sm-block bg-white shadow-md border animate-fadein rounded p-3\"\n          >\n            <span class=\"group-icon px-2 py-2 float-start\">\n              <i class=\"fi fi-bars-2\"></i>\n              <i class=\"fi fi-close\"></i>\n            </span>\n            <span class=\"h5 py-2 m-0 float-start\"> 分类 </span>\n          </button>\n\n                    <!-- desktop only -->\n                    <h5 class=\"py-3 m-0 d-none d-lg-block\">分类</h5>\n\n                    <!-- navbar : navigation -->\n                    <ul id=\"nav_responsive\" class=\"nav flex-column d-none d-lg-block\">\n                        {%for item in classifyList%}\n                        <li\n                            class=\"nav-item {%if (item.id ==classify.id) or (classify.id in (item.arrId or [])) %}active{%endif%}\">\n                            {%if item.children%}\n                            <a class=\"nav-link px-0\" href=\"#\">\n                                <span class=\"group-icon\">\n                  <i class=\"fi fi-arrow-end\"></i>\n                  <i class=\"fi fi-arrow-down\"></i>\n                </span>\n                                <span class=\"px-2 d-inline-block\"> {{item.title}} </span>\n                            </a>\n                            {%else%}\n                            <a class=\"nav-link px-0\" href=\"{{item.url}}\">\n                                <i class=\"fi fi-arrow-end m-0 smaller\"></i>\n                                <span class=\"px-2 d-inline-block\"> {{item.title}} </span>\n                            </a>\n                            {%endif%} {%if item.children%}\n                            <ul class=\"nav flex-column ps-2\">\n                                {%for _item in item.children%}\n                                <li class=\"nav-item {%if _item.id ==classify.id%}active{%endif%}\">\n                                    <a class=\"nav-link\" href=\"{{_item.url}}\"> {{_item.title}} </a>\n                                </li>\n                                {%endfor%}\n                            </ul>\n                            {%endif%}\n                        </li>\n                        {%endfor%}\n                    </ul>\n                </nav>\n                <!-- /CATEGORIES -->\n                {%endif%} {% set subclassify = classify.id|@classify(\'sub\') %} {% for\n                item in subclassify%}\n                <!-- Suggestions -->\n                <div\n                    class=\"card border-0 shadow-xs d-block mb-3 px-3 pb-3 shadow-none-md shadow-none-xs p-0-md p-0-xs rounded\">\n                    <!-- mobile trigger : categories -->\n                    <button\n            class=\"clearfix btn btn-toggle btn-sm w-100 text-align-left shadow-md border rounded mb-1 d-block d-lg-none\"\n            data-bs-target=\"#nav_{{ item.name }}\"\n            data-toggle-container-class=\"d-none d-sm-block bg-white shadow-md border animate-fadein rounded p-3\"\n          >\n            <span class=\"group-icon px-2 py-2 float-start\">\n              <i class=\"fi fi-bars-2\"></i>\n              <i class=\"fi fi-close\"></i>\n            </span>\n            <span class=\"h5 py-2 m-0 float-start\"> {{ item.label }} </span>\n          </button>\n                    <!-- desktop only -->\n                    <h6 class=\"py-3 m-0 d-none d-lg-block\">{{ item.label }}</h6>\n                    {% if item.type==\'radios\' %}\n                    <div id=\"nav_{{ item.name }}\" class=\"checkgroup flex-column d-none d-lg-block classify-sub\"\n                        data-type=\"{{ item.type }}\" data-name=\"{{ item.name }}\" data-url=\"{{ item.url }}\"\n                        data-checkgroup-checkbox-single=\"true\">\n                        {% for v in item.options %}\n                        <div class=\"form-check mb-1\">\n                            <!-- item -->\n                            <input\n                class=\"form-check-input form-check-input-primary class-sub-input\"\n                name=\"{{ item.name }}\"\n                type=\"checkbox\"\n                value=\"{{ v.value }}\"\n                id=\"{{ item.name }}-{{ v.value }}\"\n                {%\n                if\n                v.check\n                %}checked{%\n                endif\n                %}\n              />\n                            <label\n                class=\"form-check-label\"\n                for=\"{{ item.name }}-{{ v.value }}\"\n              >\n                {{ v.label }}\n              </label>\n                        </div>\n                        {% endfor %}\n                    </div>\n                    {% elif item.type==\'checkboxes\' %}\n                    <div id=\"nav_{{ item.name }}\" class=\"checkgroup flex-column d-none d-lg-block\">\n                        <div class=\"form-check mb-2\">\n                            <!-- check all -->\n                            <input\n                data-checkall-container=\"#checkall-{{ item.name }}\"\n                class=\"form-check-input form-check-input-default class-sub-input\"\n                type=\"checkbox\"\n                value=\"\"\n                id=\"checkall-{{ item.name }}-top\"\n              />\n                            <label\n                class=\"form-check-label\"\n                for=\"checkall-{{ item.name }}-top\"\n              >\n                全选/不选\n              </label>\n                        </div>\n\n                        <div id=\"checkall-{{ item.name }}\" class=\"ps-0 classify-sub\" data-type=\"{{ item.type }}\"\n                            data-name=\"{{ item.name }}\" data-url=\"{{ item.url }}\">\n                            {% for v in item.options %}\n                            <div class=\"form-check mb-1\">\n                                <!-- item -->\n                                <input\n                  class=\"form-check-input form-check-input-primary class-sub-input\"\n                  name=\"{{ item.name }}\"\n                  type=\"checkbox\"\n                  value=\"{{ v.value }}\"\n                  id=\"{{ item.name }}-{{ v.value }}\"\n                  {%\n                  if\n                  v.check\n                  %}checked{%\n                  endif\n                  %}\n                />\n                                <label\n                  class=\"form-check-label\"\n                  for=\"{{ item.name }}-{{ v.value }}\"\n                >\n                  {{ v.label }}\n                </label>\n                            </div>\n                            {% endfor %}\n                        </div>\n                    </div>\n                    {% endif %}\n                </div>\n                <!-- /Suggestions -->\n                {% endfor %}\n                <!-- BANNER -->\n                <a href=\"#!\"\n                    class=\"mt-0 d-none d-lg-block text-center overlay-dark-hover overlay-opacity-2 rounded overflow-hidden\">\n                    <img class=\"w-100 img-fluid rounded\" src=\"/public/assets/demo.files/images/unsplash/portfolio/thumb_330/boxed-water-is-better-6RTh34xCS1M-unsplash-min.jpg\" alt=\"...\">\n                </a>\n                <h4 class=\"small text-gray-500 fw-normal mt-1 mb-0 d-none d-lg-block\">\n                    Sponsored Ad\n                </h4>\n                <!-- /BANNER -->\n            </div>\n        </div>\n    </div>\n</div>\n\n{% endblock %}\n{%block script%}\n<script src=\"/public/cms/{{\'cms\'|@templatePath}}/js/list.js\"></script>\n{%endblock%}',1,0,'4cbd5a7c-7e76-4e33-8265-1d4e93f95fe1'),(14,'2025-07-30 00:42:42','2025-07-30 00:42:42','37934d72-fe2c-4a0d-afbb-414993e63986','默认详情模板','detail','default','{% extends \"./inc_base.html\" %}\n{%block body%}class=\"header-scroll-reveal\"{%endblock%}\n{% block middle %}\n<!-- start :: blog content -->\n<div class=\"section pt-4\">\n    <div class=\"container\">\n\n        <div class=\"row g-xl-5\">\n\n            <div class=\"col-lg-9 order-2 order-lg-1\">\n\n                <div class=\"mb-4\">\n                    <nav aria-label=\"breadcrumb\">\n                        <ol class=\"breadcrumb small mb-3\">\n                            {%for item in breadcrumb%}\n                            <li class=\"breadcrumb-item\"><a href=\"{{item.url}}\">{{item.name}}</a></li>\n                            {%endfor%}\n                            <li class=\"breadcrumb-item\">详情</li>\n                        </ol>\n                    </nav>\n                    <h1 class=\"h3 mb-0\">\n                        {{detail.title}}\n                    </h1>\n                    <p class=\"d-block text-muted small\">\n                        发布时间: <time\n                            datetime=\"{{helper.moment(detail.createdAt).format(\'YYYY-MM-DD HH:mm:ss\')}}\">{{helper.moment(detail.createdAt).format(\'YYYY-MM-DD\n                            HH:mm:ss\')}}</time>\n                    </p>\n\n                </div>\n                {%if detail.models_uuid===\'e86401ba-85cb-47f7-9f53-853e26b939bd\'%}\n                <div class=\"article-format\">\n                    {{detail.cms_doc_article.content|safe}}\n                </div>\n                {%elif detail.models_uuid===\'4e0da60c-13af-4965-8f35-e2b13742398e\'%}\n                <!--\n						In order for lazyload to work, a height is required, else all images are in viewport.\n						By default, an empty png is set with 300px height:\n						http://png-pixel.com/\n					-->\n                <div class=\"row\">\n                    {% for item in detail.cms_doc_picture.content%}\n                    <div class=\"col-6 col-lg-4 mb-3\">\n\n                        <div class=\"bg-white p-2 shadow-primary-xs transition-hover-top transition-all-ease-250\">\n                            <a href=\"{{item.url}}\" data-fancybox=\"gallery\"\n                                class=\"fancybox fancybox-primary d-block overflow-hidden overlay-dark-hover overlay-opacity-2 text-decoration-none text-dark\">\n                                <img class=\"img-fluid lazy rounded\" data-src=\"{{item.url}}\" src=\"data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAEsCAQAAACoWRFeAAAAE0lEQVR42mNkYGAcRaNoFA0cAgAUvAEtNFICWAAAAABJRU5ErkJggg==\" alt=\"...\">\n                            </a>\n                            <div class=\"p-2\">\n                                <h6 class=\"m-0\">\n                                    {{item.desc}}\n                                </h6>\n                            </div>\n                        </div>\n\n                    </div>\n                    {%endfor%}\n                </div>\n\n                {%elif detail.models_uuid===\'aac4b5a3-89f2-4c41-9213-39f43dcc0860\'%}\n\n                <div class=\"row\">\n                    <div class=\"col mb-3\">\n                        {%if detail.cover_url%}\n                        <figure class=\"mb-3\">\n                            <img class=\"img-fluid\" src=\"{{detail.cover_url}}\" alt=\"...\">\n                        </figure>\n                        {%endif%}\n                        {%if detail.cms_doc_download.desc%}\n                        {{detail.cms_doc_download.desc|safe}}\n                        {%endif%}\n                    </div>\n                    <div class=\"col-12 col-lg-3 mb-3 \">\n                        <!-- specifications -->\n                        <div class=\"sticky-kit z-index-0 bg-w\">\n                            <div class=\"card\">\n                                <div class=\"card-body\">\n                                    <h3 class=\"h5\">\n                                        下载列表\n                                    </h3>\n\n                                    <!-- specs list -->\n                                    <ul class=\"list-unstyled mb-0\">\n                                        {%for item in detail.cms_doc_download.content%}\n                                        <li class=\"list-item clearfix border-bottom py-2\">\n                                            <a href=\"#\" data-bs-toggle=\"modal\" data-bs-target=\"#d-{{loop.index}}\">\n                                                <i class=\"fi {%if item.d_type===\'1\'%}fi-arrow-download{%else%}fi-cloud-download{%endif%} text-gray-400 fs-5\"></i>\n                                                <span class=\"d-inline-block px-2\">{{item.d_title}}</span>\n                                            </a>\n                                        </li>\n                                        {%endfor%}\n                                    </ul>\n                                    <!-- /specs list -->\n                                </div>\n                            </div>\n                        </div>\n                        {%for item in detail.cms_doc_download.content%}\n                        <!-- Modal -->\n                        <div class=\"modal fade\" id=\"d-{{loop.index}}\" data-bs-keyboard=\"false\" tabindex=\"-1\"\n                            aria-labelledby=\"modalCenteredLabel\" aria-hidden=\"true\">\n                            <div class=\"modal-dialog modal-dialog-centered\">\n                                <div class=\"modal-content\">\n\n                                    <div class=\"modal-body\">\n                                        {%if item.d_password%}\n                                        <h6>\n                                            密码：<code>{{item.d_password}}</code>\n                                        </h6>\n                                        {%endif%}\n                                        <div class=\"alert alert-primary mb-0\" role=\"alert\">\n                                            点击下载无响应？ 是因为浏览器阻止了弹出窗口，网址输入框的最右边有个图标，点击后允许即可！\n                                        </div>\n                                    </div>\n\n                                    <div class=\"modal-footer\">\n                                        <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">关闭</button>\n                                        <a href=\"{{item.d_url}}\" type=\"button\" class=\"btn btn-primary\"\n                                            target=\"_blank\">点击下载</a>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                        {%endfor%}\n                        <!-- /specifications -->\n                        {% if detail.description %}\n                        <div\n                            class=\"p-2 mt-3 bg-primary-soft border-start border-end border-primary border-2 text-white rounded-xl\">\n                            <h3 class=\"h6\">简介</h3>\n                            <div class=\"small\">\n                                {{detail.description}}\n                            </div>\n                        </div>\n                        {%endif%}\n\n                    </div>\n\n\n                </div>\n\n                {%endif%}\n                <p class=\"text-muted border-bottom pb-2 small mt-5\">\n                    最后更新时间: {{helper.moment(detail.updatedAt).format(\'YYYY-MM-DD HH:mm:ss\')}}\n                </p>\n                {%set tags = detail.tags|split(\',\')%}\n                {%if tags%}\n                <!-- Tags and share -->\n                <div class=\"row\">\n                    <div class=\"col-12\">\n\n                        <h4 class=\"smaller text-muted\">\n                            相关标签\n                        </h4>\n                        {%for item in tags%}\n                        <a href=\"#!\" class=\"text-dark bg-light small rounded py-2 px-3 m-1 text-decoration-none\"\n                            rel=\"nofollow\">\n                            {{item}}\n                        </a>\n                        {%endfor%}\n                    </div>\n                </div>\n                <!-- /Tags and share -->\n                {%endif%}\n\n\n\n                <!-- COMMENTS -->\n                {%if detail.cms_classify.reply%}\n                {% include \"./comment_index.html\" %}\n                {%endif%}\n                <!-- /COMMENTS -->\n\n\n\n\n\n\n\n            </div>\n\n            <div class=\"col-lg-3 order-1 order-lg-2 mb-5 d-none d-lg-block\">\n\n\n                <!-- SEARCH -->\n                <form method=\"get\" action=\"{{detail.classify_url}}\" class=\"input-group-over d-block mb-2\">\n\n                    <div class=\"form-floating mb-3\">\n                        <input required placeholder=\"内容搜索...\" id=\"blog_search\" name=\"keywords\" type=\"text\" class=\"form-control\">\n                        <label for=\"blog_search\">内容搜索...</label>\n                    </div>\n\n                    <button type=\"submit\" class=\"btn smaller\">\n									<i class=\"fi fi-search m-0\"></i>\n								</button>\n\n                </form>\n                <!-- /SEARCH -->\n\n\n\n                {%set classifyList = detail.classify_id|@classify(\'top\')%} {%if classifyList%}\n                <!-- CATEGORIES -->\n                <nav\n                    class=\"nav-deep nav-deep-light mb-3 shadow-xs shadow-none-md shadow-none-xs px-3 pb-3 p-0-md p-0-xs rounded\">\n                    <!-- mobile trigger : categories -->\n                    <button\n            class=\"clearfix btn btn-toggle btn-sm w-100 text-align-left shadow-md border rounded mb-1 d-block d-lg-none\"\n            data-bs-target=\"#nav_responsive\"\n            data-toggle-container-class=\"d-none d-sm-block bg-white shadow-md border animate-fadein rounded p-3\"\n          >\n            <span class=\"group-icon px-2 py-2 float-start\">\n              <i class=\"fi fi-bars-2\"></i>\n              <i class=\"fi fi-close\"></i>\n            </span>\n            <span class=\"h5 py-2 m-0 float-start\"> 分类 </span>\n          </button>\n\n                    <!-- desktop only -->\n                    <h5 class=\"py-3 m-0 d-none d-lg-block\">分类</h5>\n\n                    <!-- navbar : navigation -->\n                    <ul id=\"nav_responsive\" class=\"nav flex-column d-none d-lg-block\">\n                        {%for item in classifyList%}\n                        <li\n                            class=\"nav-item {%if (item.id ==classify.id) or (classify.id in (item.arrId or [])) %}active{%endif%}\">\n                            {%if item.children%}\n                            <a class=\"nav-link px-0\" href=\"#\">\n                                <span class=\"group-icon\">\n                  <i class=\"fi fi-arrow-end\"></i>\n                  <i class=\"fi fi-arrow-down\"></i>\n                </span>\n                                <span class=\"px-2 d-inline-block\"> {{item.title}} </span>\n                            </a>\n                            {%else%}\n                            <a class=\"nav-link px-0\" href=\"{{item.url}}\">\n                                <i class=\"fi fi-arrow-end m-0 smaller\"></i>\n                                <span class=\"px-2 d-inline-block\"> {{item.title}} </span>\n                            </a>\n                            {%endif%} {%if item.children%}\n                            <ul class=\"nav flex-column ps-2\">\n                                {%for _item in item.children%}\n                                <li class=\"nav-item {%if _item.id ==classify.id%}active{%endif%}\">\n                                    <a class=\"nav-link\" href=\"{{_item.url}}\"> {{_item.title}} </a>\n                                </li>\n                                {%endfor%}\n                            </ul>\n                            {%endif%}\n                        </li>\n                        {%endfor%}\n                    </ul>\n                </nav>\n                <!-- /CATEGORIES -->\n                {%endif%}\n                {% set hotlist = \'cms_doc\'|@findAll({\n                where:{\n                classify_id:detail.classify_id\n                },\n                offset: 0,\n                limit: 5,\n                order:[[\'view\',\'desc\']]\n                })%}\n                {%if hotlist%}\n                <div class=\"d-none d-lg-block\">\n                    <h3 class=\"h5 mt-5 mt-0-xs\">热点</h3>\n\n                    <ul class=\"list-unstyled mb-0\">\n                        {%for item in hotlist%}\n                        <li class=\"list-item d-flex align-items-center position-relative mt-4\">\n                            <div class=\"ratio ratio-16x9 bg-light me-3\" style=\"max-width: 50px;\">\n                                <div class=\"bg-cover rounded\" style=\"background-image:url({{item.cover_url}});\"></div>\n                            </div>\n                            <a href=\"/cms/detail/{{item.id}}\"\n                                class=\"link-normal small stretched-link\">{{item.title|truncate(20, true, \"...\")}}</a>\n                        </li>\n                        {%endfor%}\n                    </ul>\n\n                </div>\n                {%endif%}\n                <!-- mobile trigger : expand -->\n\n                <button class=\"mt-3 clearfix btn btn-toggle btn-sm w-100 text-align-left shadow-md border rounded mb-1 d-block d-lg-none\" data-bs-target=\"#sidebar_expand_mobile\" data-toggle-container-class=\"d-none d-sm-block bg-white shadow-md border animate-fadein rounded p-3\">\n								<span class=\"group-icon px-2 py-2 float-start\">\n									<i class=\"fi fi-bars-2\"></i>\n									<i class=\"fi fi-close\"></i>\n								</span>\n\n								<span class=\"h5 py-2 m-0 float-start \">\n									Explore\n								</span>\n							</button>\n\n                <div id=\"sidebar_expand_mobile\" class=\"d-none d-lg-block\">\n                    <!-- BANNER -->\n                    <a href=\"#!\"\n                        class=\"mt-3 d-block text-center overlay-dark-hover overlay-opacity-2 rounded overflow-hidden\">\n                        <img class=\"w-100 img-fluid rounded\" src=\"/public/assets/demo.files/images/unsplash/portfolio/thumb_330/boxed-water-is-better-6RTh34xCS1M-unsplash-min.jpg\" alt=\"...\">\n                    </a>\n                    <h4 class=\"small text-gray-500 fw-normal mt-1 mb-0\">\n                        Sponsored Ad\n                    </h4>\n                    <!-- /BANNER -->\n\n                </div>\n\n            </div>\n\n        </div>\n\n    </div>\n</div>\n<!-- end :: blog content -->\n\n{% endblock %}\n{%block script%}\n<script>\n    //评论\n  var cms_comments_callback = function(from,data){\n		if(data.status===1000){\n          $.SOW.core.toast.show(\'danger\', \'Error\', data.msg, \'top-end\');\n        }else{\n          $.SOW.core.toast.show(\'success\', \'Success\', data.msg, \'top-end\');\n          $(from).find(\'[name=\"content\"]\').empty()\n					$.SOW.core.ajax_content.__ajaxDivProcess(\'cms_comments_container\', \'/cms/comments/ajaxList?doc_id={{detail.id}}\', \'#cms_comments_container\',$.SOW.core.ajax_content.config.method,null,$.SOW.core.ajax_content.config.callback_function,$.SOW.core.ajax_content.config.callback_before_push);\n        }\n	}\n	var cms_comments_reply_callback = function(from,data){\n		if(data.status===1000){\n          $.SOW.core.toast.show(\'danger\', \'Error\', data.msg, \'top-end\');\n        }else{\n          $.SOW.core.toast.show(\'success\', \'Success\', data.msg, \'top-end\');\n          $(from).find(\'[name=\"content\"]\').empty()\n					$(\'#sow_ajax_modal\').modal(\'hide\');\n					$.SOW.core.ajax_content.__ajaxDivProcess(\'cms_comments_container\', \'/cms/comments/ajaxList?doc_id={{detail.id}}&page=\'+data.data, \'#cms_comments_container\',$.SOW.core.ajax_content.config.method,null,$.SOW.core.ajax_content.config.callback_function,$.SOW.core.ajax_content.config.callback_before_push);\n        }\n	 }\n</script>\n{%endblock%}',1,0,'ad47e76d-3e11-49e0-84d5-3b894e06ccd9'),(15,'2025-07-30 00:42:42','2025-07-30 00:42:42','37934d72-fe2c-4a0d-afbb-414993e63986','默认公共基础模板','inc','base','<!doctype html>\n<html lang=\"zh-CN\" xmlns=\"http://www.w3.org/1999/xhtml\">\n\n<head>\n    <meta charset=\"UTF-8\">\n    <title>{{ctx.meta_title}}-{{ctx.app.config.sys.name}}</title>\n    <meta name=\"keywords\" content=\"{{ctx.keywords}}\" />\n    <meta name=\"description\" content=\"{{ctx.description}}\" />\n    <meta name=\"viewport\" content=\"width=device-width, maximum-scale=5, initial-scale=1\">\n    <!--[if IE]><meta http-equiv=\'X-UA-Compatible\' content=\'IE=edge,chrome=1\'><![endif]-->\n\n    <!-- preloading icon font is helping to speed up a little bit -->\n    <link rel=\"preload\" href=\"/public/assets/fonts/flaticon/Flaticon.woff2\" as=\"font\" type=\"font/woff2\" crossorigin>\n    <link rel=\"stylesheet\" href=\"/public/assets/css/core.min.css\">\n    <link rel=\"stylesheet\" href=\"/public/assets/css/vendor_bundle.min.css\">\n\n\n    <link rel=\"stylesheet\" href=\"/public/cms/{{\'cms\'|@templatePath}}/css/app.css\">\n    <!-- favicon -->\n    <link rel=\"shortcut icon\" href=\"/public/cms/{{\'cms\'|@templatePath}}/favicon.ico\">\n    <link rel=\"apple-touch-icon\" href=\"/public/cms/{{\'cms\'|@templatePath}}/logo/icon_512x512.png\">\n\n</head>\n\n<body {%block body%}{%endblock%}>\n    <!-- wrapper -->\n    <div id=\"wrapper\">\n        {# 网站头部 #}\n        {% include \"./inc_header.html\" %}\n        {# 网站头部结束 #}\n\n        {# 网站内容 #}\n        {% block middle %}{% endblock %}\n        {# 网站内容结束 #}\n\n        {# 网站底部 #}\n        {% include \"./inc_footer.html\" %}\n        {# 网站底部结束 #}\n    </div>\n    <!-- /#wrapper -->\n    <script src=\"/public/assets/js/core.min.js\"></script>\n    <div id=\"page_js_files\">\n        <script>\n            //登录\n        var mc_sign_callback = function(form,data){\n          if(data.status===1000){\n            $.SOW.core.toast.show(\'danger\', \'Error\', data.msg, \'top-end\');\n          }else{\n            $.SOW.core.toast.show(\'success\', \'Success\', data.msg, \'top-end\');\n            location.reload();\n          }\n        }\n        //注册\n        var mc_signup_callback = function(form,data){\n        if(data.status===1000){\n          $.SOW.core.toast.show(\'danger\', \'Error\', data.msg, \'top-end\');\n        }else{\n          $.SOW.core.toast.show(\'success\', \'Success\', data.msg, \'top-end\');\n          $(form)[0].reset();\n          $(\"#accordionAccountSignUp\").removeClass(\'show\');\n          $(\"#accordionAccountSignIn\").addClass(\'show\')\n        }\n        }\n        </script>\n        <!-- additional javascripts inside here -->\n        {%block script%}{%endblock%}\n    </div>\n\n</body>\n\n</html>',1,0,'80652219-2c34-4856-b721-7504e4d7ad1a'),(16,'2025-07-30 00:42:42','2025-07-30 00:42:42','37934d72-fe2c-4a0d-afbb-414993e63986','默认公共头部模板','inc','header','<!-- Header -->\n<header id=\"header\" class=\"shadow-primary-xs\">\n\n    <!-- TOP BAR -->\n    {# <div id=\"top_bar\" class=\"bg-light\">\n        <!-- optional if body.header-sticky is present: add .js-ignore class to ignore autohide and stay visible all the time -->\n        <div class=\"container\">\n\n            <div class=\"text-nowrap\">\n                <!-- change with .scrollable-horizontal to horizontally scroll, if -only- no dropdown is present -->\n                <div class=\"d-flex justify-content-between\">\n\n                    <div class=\"d-inline-block float-start\">\n                        <ul class=\"list-inline m-0\">\n\n                            <!-- LANGUAGE -->\n                            <li class=\"dropdown list-inline-item m-0\">\n\n                                <a id=\"topDDLanguage\" href=\"#\" class=\"py-2 d-inline-block\" data-bs-toggle=\"dropdown\"\n                                    aria-expanded=\"false\" aria-haspopup=\"true\">\n                                    <i class=\"flag flag-us\"></i>\n                                    <span class=\"text-muted px-2\">English</span>\n                                </a>\n\n                                <div aria-labelledby=\"topDDLanguage\"\n                                    class=\"dropdown-menu dropdown-menu-hover p-1 pb-0 scrollable-vertical\">\n                                    <a href=\"#\" class=\"active dropdown-item text-muted text-truncate lh-1 rounded mb-1\">\n                                        <i class=\"flag flag-us\"></i>\n                                        English\n                                    </a>\n                                    <a href=\"#\" class=\"dropdown-item text-muted text-truncate lh-1 rounded mb-1\">\n                                        <i class=\"flag flag-de\"></i>\n                                        German\n                                    </a>\n                                    <a href=\"#\" class=\"dropdown-item text-muted text-truncate lh-1 rounded mb-1\">\n                                        <i class=\"flag flag-fr\"></i>\n                                        Francaise\n                                    </a>\n                                </div>\n\n                            </li>\n                            <!-- /LANGUAGE -->\n\n\n                            <!-- CURRENCY -->\n                            <li class=\"dropdown list-inline-item m-0\">\n\n                                <span class=\"text-muted\">/</span><!-- optional separator -->\n\n                                <a id=\"topDDCurrency\" href=\"#\" class=\"py-2 d-inline-block\" data-bs-toggle=\"dropdown\"\n                                    aria-expanded=\"false\">\n                                    <span class=\"text-muted px-2\">USD</span>\n                                </a>\n\n                                <div aria-labelledby=\"topDDCurrency\"\n                                    class=\"dropdown-menu dropdown-menu-hover text-uppercase text-center p-1 pb-0 w-auto\">\n                                    <a href=\"#\" class=\"active dropdown-item text-muted text-truncate lh-1 rounded mb-1\">\n                                        USD\n                                    </a>\n                                    <a href=\"#\" class=\"dropdown-item text-muted text-truncate lh-1 rounded mb-1\">\n                                        EUR\n                                    </a>\n                                    <a href=\"#\" class=\"dropdown-item text-muted text-truncate lh-1 rounded mb-1\">\n                                        GBP\n                                    </a>\n                                </div>\n\n                            </li>\n                            <!-- /CURRENCY -->\n\n                        </ul>\n                    </div>\n\n\n                    <div class=\"d-inline-block float-end\">\n\n                        <ul class=\"list-inline m-0\">\n\n                            <li class=\"dropdown list-inline-item\">\n\n                                <a href=\"tel:+01-555-5555\" class=\"p-2 d-inline-block fw-medium\">\n                                    <i class=\"float-start fi fi-phone\"></i> (+01) 555-5555\n                                </a>\n\n                            </li>\n\n                        </ul>\n\n                    </div>\n\n                </div>\n            </div>\n\n        </div>\n    </div> #}\n    <!-- /TOP BAR -->\n\n\n\n\n    <!-- Navbar -->\n    <div class=\"container position-relative\">\n        <nav class=\"navbar navbar-expand-lg navbar-light justify-content-lg-between justify-content-md-inherit\">\n\n            <div class=\"align-items-start\">\n\n                <!-- mobile menu button : show -->\n                <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#navbarMainNav\" aria-controls=\"navbarMainNav\" aria-expanded=\"false\" aria-label=\"Toggle navigation\">\n								<svg width=\"25\" viewBox=\"0 0 20 20\">\n									<path d=\"M 19.9876 1.998 L -0.0108 1.998 L -0.0108 -0.0019 L 19.9876 -0.0019 L 19.9876 1.998 Z\"></path>\n									<path d=\"M 19.9876 7.9979 L -0.0108 7.9979 L -0.0108 5.9979 L 19.9876 5.9979 L 19.9876 7.9979 Z\"></path>\n									<path d=\"M 19.9876 13.9977 L -0.0108 13.9977 L -0.0108 11.9978 L 19.9876 11.9978 L 19.9876 13.9977 Z\"></path>\n									<path d=\"M 19.9876 19.9976 L -0.0108 19.9976 L -0.0108 17.9976 L 19.9876 17.9976 L 19.9876 19.9976 Z\"></path>\n								</svg>\n							</button>\n\n                <!-- navbar : brand (logo) -->\n                <a class=\"navbar-brand\" href=\"/\">\n                    <img src=\"/public/cms/{{\'cms\'|@templatePath}}/images/logo/logo_dark.svg\" width=\"145\" height=\"38\" alt=\"...\">\n                </a>\n\n            </div>\n\n\n\n\n            <!-- Menu -->\n            <!--\n\n							Dropdown Classes (should be added to primary .dropdown-menu only, dropdown childs are also affected)\n								.dropdown-menu-dark 		- dark dropdown (desktop only, will be white on mobile)\n								.dropdown-menu-hover 		- open on hover\n								.dropdown-menu-clean 		- no background color on hover\n								.dropdown-menu-invert 		- open dropdown in oposite direction (left|right, according to RTL|LTR)\n								.dropdown-menu-uppercase 	- uppercase text (font-size is scalled down to 13px)\n								.dropdown-click-ignore 		- keep dropdown open on inside click (useful on forms inside dropdown)\n\n								Repositioning long dropdown childs (Example: Pages->Account)\n									.dropdown-menu-up-n100 		- open up with top: -100px\n									.dropdown-menu-up-n100 		- open up with top: -150px\n									.dropdown-menu-up-n180 		- open up with top: -180px\n									.dropdown-menu-up-n220 		- open up with top: -220px\n									.dropdown-menu-up-n250 		- open up with top: -250px\n									.dropdown-menu-up 			- open up without negative class\n\n\n								Dropdown prefix icon (optional, if enabled in variables.scss)\n									.prefix-link-icon .prefix-icon-dot 		- link prefix\n									.prefix-link-icon .prefix-icon-line 	- link prefix\n									.prefix-link-icon .prefix-icon-ico 		- link prefix\n									.prefix-link-icon .prefix-icon-arrow 	- link prefix\n\n								.nav-link.nav-link-caret-hide 	- no dropdown icon indicator on main link\n								.nav-item.dropdown-mega 		- required ONLY on fullwidth mega menu\n\n								Mobile animation - add to .navbar-collapse:\n								.navbar-animate-fadein\n								.navbar-animate-fadeinup\n								.navbar-animate-bouncein\n\n						-->\n            <div class=\"collapse navbar-collapse navbar-animate-fadein\" id=\"navbarMainNav\">\n\n\n                <!-- navbar : mobile menu -->\n                <div class=\"navbar-xs d-none\">\n                    <!-- .sticky-top -->\n\n                    <!-- mobile menu button : close -->\n                    <button class=\"navbar-toggler pt-0\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#navbarMainNav\" aria-controls=\"navbarMainNav\" aria-expanded=\"false\" aria-label=\"Toggle navigation\">\n									<svg width=\"20\" viewBox=\"0 0 20 20\">\n										<path d=\"M 20.7895 0.977 L 19.3752 -0.4364 L 10.081 8.8522 L 0.7869 -0.4364 L -0.6274 0.977 L 8.6668 10.2656 L -0.6274 19.5542 L 0.7869 20.9676 L 10.081 11.679 L 19.3752 20.9676 L 20.7895 19.5542 L 11.4953 10.2656 L 20.7895 0.977 Z\"></path>\n									</svg>\n								</button>\n\n                    <!-- \n									Mobile Menu Logo \n									Logo : height: 70px max\n								-->\n                    <a class=\"navbar-brand\" href=\"index.html\">\n                        <img src=\"/public/cms/{{\'cms\'|@templatePath}}/images/logo/logo_dark.svg\" width=\"110\" height=\"38\" alt=\"...\">\n                    </a>\n\n                </div>\n                <!-- /navbar : mobile menu -->\n\n\n\n                <!-- navbar : navigation -->\n                <ul class=\"navbar-nav\">\n                    <!-- Menu -->\n                    <!--\n\n									Dropdown Classes (should be added to primary .dropdown-menu only, dropdown childs are also affected)\n										.dropdown-menu-dark 		- dark dropdown (desktop only, will be white on mobile)\n										.dropdown-menu-hover 		- open on hover\n										.dropdown-menu-clean 		- no background color on hover\n										.dropdown-menu-invert 		- open dropdown in oposite direction (left|right, according to RTL|LTR)\n										.dropdown-menu-uppercase 	- uppercase text (font-size is scalled down to 13px)\n										.dropdown-click-ignore 		- keep dropdown open on inside click (useful on forms inside dropdown)\n\n										Repositioning long dropdown childs (Example: Pages->Account)\n											.dropdown-menu-up-n100 		- open up with top: -100px\n											.dropdown-menu-up-n100 		- open up with top: -150px\n											.dropdown-menu-up-n180 		- open up with top: -180px\n											.dropdown-menu-up-n220 		- open up with top: -220px\n											.dropdown-menu-up-n250 		- open up with top: -250px\n											.dropdown-menu-up 			- open up without negative class\n\n\n										Dropdown prefix icon (optional, if enabled in variables.scss)\n											.prefix-link-icon .prefix-icon-dot 		- link prefix\n											.prefix-link-icon .prefix-icon-line 	- link prefix\n											.prefix-link-icon .prefix-icon-ico 		- link prefix\n											.prefix-link-icon .prefix-icon-arrow 	- link prefix\n\n										.nav-link.nav-link-caret-hide 	- no dropdown icon indicator on main link\n										.nav-item.dropdown-mega 		- required ONLY on fullwidth mega menu\n\n								-->\n                    <!-- mobile only image + simple search (d-block d-sm-none) -->\n                    <li class=\"nav-item d-block d-sm-none\">\n\n                        <!-- image -->\n                        <div class=\"mb-4\">\n                            <img width=\"600\" height=\"600\" class=\"img-fluid\" src=\"/public/assets/demo.files/svg/artworks/people_crossbrowser.svg\" alt=\"...\">\n                        </div>\n\n                        <!-- search -->\n                        {#\n                        <form method=\"get\" action=\"#!search\"\n                            class=\"input-group-over mb-4 bg-light p-2 form-control-pill\">\n                            <input type=\"text\" name=\"keyword\" value=\"\" placeholder=\"Quick search...\" class=\"form-control border-dashed\">\n                            <button class=\"btn btn-sm fi fi-search mx-3\"></button>\n                        </form>\n                        #}\n                    </li>\n                    {%for item in \'header\'|@navigation%}\n                    <li class=\"nav-item dropdown\">\n                        <a href=\"{{item.url}}\" {%if item.children%}id=\"nav_{{item.id}}\" data-bs-toggle=\"dropdown\"\n                            aria-haspopup=\"true\" aria-expanded=\"false\" {%endif%} {%if item.target%}target=\"_blank\"\n                            {%endif%} class=\"nav-link {%if item.children%}dropdown-toggle{%endif%}\">\n                            {{item.title}}\n                        </a>\n                        {%if item.children%}\n                        <div aria-labelledby=\"nav_{{item.id}}\"\n                            class=\"dropdown-menu dropdown-menu-clean dropdown-menu-hover dropdown-fadeinup\">\n                            <ul class=\"list-unstyled m-0 p-0\">\n                                {%for _item in item.children%}\n                                <li class=\"dropdown-item dropdown\">\n                                    <a class=\"dropdown-link\" href=\"{{_item.url}}\" {%if\n                                        _item.children%}data-bs-toggle=\"dropdown\" {%endif%} {%if\n                                        _item.target%}target=\"_blank\" {%endif%}>{{_item.title}}</a>\n                                    {%if _item.children%}\n                                    <ul\n                                        class=\"dropdown-menu dropdown-menu-hover dropdown-menu-block-md shadow-lg rounded-xl border-0 m-0\">\n                                        {%for __item in _item.children%}\n                                        <li class=\"dropdown-item\"><a href=\"{{__item.url}}\" {%if\n                                                __item.target%}target=\"_blank\" {%endif%}\n                                                class=\"dropdown-link\">{{__item.title}}</a></li>\n                                        {%endfor%}\n                                    </ul>\n                                    {%endif%}\n                                </li>\n                                {%endfor%}\n                            </ul>\n                        </div>\n                        {%endif%}\n                    </li>\n                    {%endfor%}\n\n                    <!-- social icons : mobile only -->\n                    {#\n                    <li class=\"nav-item d-block d-sm-none text-center mb-4\">\n\n                        <h3 class=\"h6 text-muted\">Follow Us</h3>\n\n                        <!-- facebook -->\n                        <a href=\"#\" class=\"btn btn-sm btn-facebook transition-hover-top mb-2 rounded-circle text-white\"\n                            rel=\"noopener\">\n                            <i class=\"fi fi-social-facebook\"></i>\n                        </a>\n\n                        <!-- twitter -->\n                        <a href=\"#\" class=\"btn btn-sm btn-twitter transition-hover-top mb-2 rounded-circle text-white\"\n                            rel=\"noopener\">\n                            <i class=\"fi fi-social-twitter\"></i>\n                        </a>\n\n                        <!-- linkedin -->\n                        <a href=\"#\" class=\"btn btn-sm btn-linkedin transition-hover-top mb-2 rounded-circle text-white\"\n                            rel=\"noopener\">\n                            <i class=\"fi fi-social-linkedin\"></i>\n                        </a>\n\n                        <!-- youtube -->\n                        <a href=\"#\" class=\"btn btn-sm btn-youtube transition-hover-top mb-2 rounded-circle text-white\"\n                            rel=\"noopener\">\n                            <i class=\"fi fi-social-youtube\"></i>\n                        </a>\n\n                    </li>\n\n\n\n                    <!-- Get Smarty : mobile only (d-block d-sm-none)-->\n                    <li class=\"nav-item d-block d-sm-none\">\n                        <a target=\"_blank\" href=\"#buy_now\" class=\"btn w-100 btn-primary shadow-none text-white m-0\">\n                            Get Smarty\n                        </a>\n                    </li>\n                    #}\n                </ul>\n                <!-- /navbar : navigation -->\n\n\n            </div>\n\n\n\n\n\n            <!-- OPTIONS -->\n            <ul class=\"list-inline list-unstyled mb-0 d-flex align-items-end\">\n                {%if ctx.userInfo%}\n                <li class=\"list-inline-item mx-1 dropdown\">\n\n                    <a href=\"#\" aria-label=\"Account Options\" id=\"dropdownAccountOptions\"\n                        class=\"btn btn-sm rounded-circle btn-light bg-transparent text-muted shadow-none\"\n                        data-bs-toggle=\"dropdown\" aria-expanded=\"false\" aria-haspopup=\"true\">\n                        <span class=\"group-icon\">\n										{%if ctx.userInfo.avatar %}\n										<i class=\"fi avatar avatar-xs rounded-circle\" style=\"background-image:url({{ctx.userInfo.avatar}})\"></i>\n										{%else%}\n										<i class=\"fi fi-users\"></i>\n										{%endif%}\n										<i class=\"fi fi-close\"></i>\n									</span>\n                    </a>\n\n\n                    <!--\n									\n									Dropdown Classes\n										.dropdown-menu-dark 		- dark dropdown (desktop only, will be white on mobile)\n										.dropdown-menu-hover 		- open on hover\n										.dropdown-menu-clean 		- no background color on hover\n										.dropdown-menu-invert 		- open dropdown in oposite direction (left|right, according to RTL|LTR)\n										.dropdown-click-ignore 		- keep dropdown open on inside click (useful on forms inside dropdown)\n\n										Dropdown prefix icon (optional, if enabled in variables.scss)\n											.prefix-link-icon .prefix-icon-dot 		- link prefix\n											.prefix-link-icon .prefix-icon-line 	- link prefix\n											.prefix-link-icon .prefix-icon-ico 		- link prefix\n											.prefix-link-icon .prefix-icon-arrow 	- link prefix\n\n											.prefix-icon-ignore 					- ignore, do not use on a specific link\n\n								-->\n                    <!-- dropdown -->\n                    <div aria-labelledby=\"dropdownAccountOptions\"\n                        class=\"list-unstyled dropdown-menu dropdown-menu-clean dropdown-click-ignore end-0 py-2 rounded-xl\"\n                        style=\"min-width:215px;\">\n\n                        <div class=\"dropdown-header px-4 mb-1 text-wrap fw-medium\">{{ctx.userInfo.username}}</div>\n                        <div class=\"dropdown-divider mb-3\"></div>\n                        <a class=\"dropdown-item active\" href=\"/mc/index\">\n                            <svg class=\"text-gray-600 float-start\" width=\"18px\" height=\"18px\" viewBox=\"0 0 16 16\"\n                                xmlns=\"http://www.w3.org/2000/svg\" fill=\"currentColor\">\n                                <path fill-rule=\"evenodd\"\n                                    d=\"M8 3.293l6 6V13.5a1.5 1.5 0 0 1-1.5 1.5h-9A1.5 1.5 0 0 1 2 13.5V9.293l6-6zm5-.793V6l-2-2V2.5a.5.5 0 0 1 .5-.5h1a.5.5 0 0 1 .5.5z\">\n                                </path>\n                                <path fill-rule=\"evenodd\"\n                                    d=\"M7.293 1.5a1 1 0 0 1 1.414 0l6.647 6.646a.5.5 0 0 1-.708.708L8 2.207 1.354 8.854a.5.5 0 1 1-.708-.708L7.293 1.5z\">\n                                </path>\n                            </svg>\n                            <span>会员中心</span>\n                        </a>\n                      \n                        <a class=\"dropdown-item\" href=\"/mc/setup\">\n                            <svg class=\"text-gray-600 float-start\" width=\"18px\" height=\"18px\" viewBox=\"0 0 16 16\"\n                                xmlns=\"http://www.w3.org/2000/svg\" fill=\"currentColor\">\n                                <path fill-rule=\"evenodd\"\n                                    d=\"M.102 2.223A3.004 3.004 0 0 0 3.78 5.897l6.341 6.252A3.003 3.003 0 0 0 13 16a3 3 0 1 0-.851-5.878L5.897 3.781A3.004 3.004 0 0 0 2.223.1l2.141 2.142L4 4l-1.757.364L.102 2.223zm13.37 9.019L13 11l-.471.242-.529.026-.287.445-.445.287-.026.529L11 13l.242.471.026.529.445.287.287.445.529.026L13 15l.471-.242.529-.026.287-.445.445-.287.026-.529L15 13l-.242-.471-.026-.529-.445-.287-.287-.445-.529-.026z\">\n                                </path>\n                            </svg>\n                            <span>账户设置</span>\n                        </a>\n                        <div class=\"dropdown-divider mt-3\"></div>\n                        <a href=\"/mc/logout\" title=\"退出登录\" class=\"dropdown-item mt-1\">\n                            <i class=\"fi fi-power float-start\"></i>\n                            退出登录\n                        </a>\n                    </div>\n\n                </li>\n                {%else%}\n                <li class=\"list-inline-item mx-1 dropdown\">\n                    <a href=\"#\" data-href=\"/mc/login\" data-ajax-modal-container=\"#mc_login\" data-ajax-modal-size=\"\"\n                        data-ajax-modal-centered=\"true\" data-ajax-modal-callback-function=\"\"\n                        class=\"js-ajax-modal btn btn-sm btn-primary bg-gradient\" data-bs-toggle=\"tooltip\"\n                        data-bs-placement=\"bottom\" title=\"登录/注册\">\n                        登录\n                    </a>\n                </li>\n                {%endif%}\n            </ul>\n            <!-- /OPTIONS -->\n        </nav>\n\n    </div>\n    <!-- /Navbar -->\n\n</header>\n<!-- /Header -->\n\n<!-- custom structure -->\n<div id=\"mc_login\" class=\"modal fade\" role=\"dialog\" tabindex=\"-1\" aria-hidden=\"true\">\n    <div class=\"modal-dialog\" role=\"document\">\n\n        <div class=\"modal-content\">\n            <!-- content added by ajax -->\n        </div>\n\n    </div>\n</div>',1,0,'61e43d5c-fc52-489f-8ca7-ca3c0864245f'),(17,'2025-07-30 00:42:42','2025-07-30 00:42:42','37934d72-fe2c-4a0d-afbb-414993e63986','默认公共底部模板','inc','footer','<!-- Footer -->\n<footer id=\"footer\" class=\"footer-dark\">\n\n    <!-- expandable : hidden by default -->\n    <div id=\"footer_expand\" class=\"collapse\">\n        <div class=\"container py-3\">\n      {%set footernav = \'footer\'|@navigation%}\n      {%if footernav|length>0%}\n            <ul class=\"mt-3 mb-0 breadcrumb bg-transparent p-0 block-xs\">\n                {%for item in footernav%}\n                <li class=\"breadcrumb-item\"><a href=\"{{item.url}}\" {%if item.target%}target=\"_blank\"{%endif%}>{{item.title}}</a></li>\n                {%endfor%}\n            </ul>\n       {%endif%}\n            <div class=\"text-muted mt-3\">\n               {{ctx.app.config.sys.description|safe}}\n            </div>\n\n        </div>\n    </div>\n    <!-- /expandable : hidden by default -->\n\n\n    <div class=\"bg-distinct py-3 clearfix\">\n\n        <div class=\"container clearfix fw-light text-center-xs position-relative\">\n\n\n            <div class=\"clearfix float-start float-none-xs\">\n\n                <!-- badge expand info -->\n                <span id=\"footer_expand_badge\" class=\"badge bg-secondary rounded-pill p-2 position-absolute start-0 mt-n5 mx-2 position-relative small fw-normal\">\n								<i class=\"arrow arrow-bottom border-secondary mx-1 mb-2\"></i>\n								单击展开\n							</span>\n\n\n                <!-- footer expand toggler -->\n                <a href=\"#footer_expand\" data-toggle-target=\"#footer_expand_badge\"\n                    data-toggle-container-class=\"hide-force\" data-offset=\"-100%\" data-speed=\"600\"\n                    class=\"scroll-to btn-toggle btn float-start overlay-dark overlay-opacity-2 overflow-hidden text-decoration-none px-3 rounded mt-n2 mb-n2\"\n                    data-bs-toggle=\"collapse\" rel=\"noopener\" aria-expanded=\"false\">\n\n                    <span class=\"group-icon\">\n									<i class=\"fi fi-menu-dots fs-4\"></i>\n									<i class=\"fi fi-close fs-4\"></i>\n								</span>\n\n                </a>\n\n                <!-- copyright -->\n                <div class=\"fs-6 py-2 float-start float-none-xs m-0-xs\">\n                    &copy; <em class=\"text-danger-gradient fw-bold fs-5\">CmsWing</em> 🧣 <span class=\"smaller bg-gradient-dark text-warning  border-start border-end border-dark border-2 rounded-xl p-1\">\n									<a class=\"text-warning\" target=\"_blank\" rel=\"noopener\" href=\"http://beian.miit.gov.cn/\">{{ctx.app.config.sys.icp}}</a>\n								</span>\n                </div>\n\n                <div class=\"clearfix mt-2 d-block d-sm-none\">\n                    <!-- mobile spacer -->\n                </div>\n            </div>\n\n        </div>\n\n    </div>\n\n</footer>\n<!-- /Footer -->',1,0,'1fb12804-2148-467c-a182-02e4388d30f0'),(18,'2025-07-30 00:42:42','2025-07-30 00:42:42','37934d72-fe2c-4a0d-afbb-414993e63986','默认评论模板','comment','index','<div class=\"clearfix mt-5\">\n    <h3 class=\"mb-4\">评论</h3>\n    {%if not ctx.userInfo%}\n    <div class=\"alert alert-primary\" role=\"alert\">\n        你还没有登录，请先 <a href=\"#\" data-href=\"/mc/login\" data-ajax-modal-container=\"#mc_login\" data-ajax-modal-size=\"\"\n            data-ajax-modal-centered=\"true\" data-ajax-modal-callback-function=\"\"\n            class=\"alert-link js-ajax-modal\">登录/注册</a> ！\n    </div>\n    {%else%}\n    <!-- already logged in -->\n    <span class=\"d-block text-muted small mb-1\">\n    登录用户: <b>{{ctx.userInfo.username}}</b>. \n    不是你吗? 请 <a rel=\"nofollow\" href=\"/mc/logout?url={{ctx.url}}\">退出登录!</a>\n  </span>\n\n    <!-- Write Comment Form -->\n    <form novalidate method=\"post\" action=\"/cms/comments/add\"\n        class=\"js-ajax bs-validate d-block bg-white shadow-primary-xs rounded p-3 mb-5\" data-ajax-update-url=\"false\"\n        data-ajax-show-loading-icon=\"true\"\n        data-error-toast-text=\"<i class=\'fi fi-circle-spin fi-spin float-start\'></i> 请填写所有必填字段！\"\n        data-error-toast-delay=\"3000\" data-error-toast-position=\"top-center\" data-error-scroll-up=\"true\"\n        data-ajax-callback-function=\"cms_comments_callback\">\n        <div class=\"clearfix mb-3\">\n\n            <div class=\"form-floating\">\n                <textarea class=\"medium-editor bg-white border p-3 rounded w-100\" required style=\"min-height:120px\" id=\"comment_description\" name=\"content\"\n        data-placeholder=\"请输入内容...\"\n        data-lng-save=\"保存\"\n        data-lng-clear=\"清空\"\n        data-lng-link=\"请输入链接地址\"\n        data-btn-picker=\"true\"\n        data-btn-bold=\"true\"\n        data-btn-italic=\"true\"\n        data-btn-underline=\"true\"\n        data-btn-link=\"true\"\n        data-btn-h1=\"false\"\n        data-btn-h2=\"false\"\n        data-btn-h3=\"false\"\n        data-btn-h4=\"true\"\n        data-btn-h5=\"true\"\n        data-btn-h6=\"true\"\n        data-btn-unordered=\"true\"\n        data-btn-ordered=\"true\"\n        ></textarea>\n            </div>\n        </div>\n        <input type=\"hidden\" name=\"doc_id\" value=\"{{detail.id}}\">\n        <button type=\"submit\" class=\"btn btn-primary btn-sm\">\n      提交评论\n    </button>\n    </form>\n    <!-- /Write Comment Form -->\n    {%endif%}\n    <!-- LIST COMMENTS -->\n\n    <!-- ajax container - content loaded on page load -->\n    <div class=\"js-ajax\" data-ajax-url=\"/cms/comments/ajaxList?doc_id={{detail.id}}\" id=\"cms_comments_container\">\n        <!-- ajax content -->\n    </div>\n    <!-- /LIST COMMENTS -->\n\n\n\n</div>',1,0,'40c21cf3-a5ac-46aa-a310-dbdfacd14cea'),(19,'2025-07-30 00:42:42','2025-07-30 00:42:42','37934d72-fe2c-4a0d-afbb-414993e63986','默认评论列表模板','comment','ajax_list','<h3 class=\"mb-4\">{{list.count}} 条评论</h3>\n{%for item in list.rows%}\n<!-- Comment 1 + Reply -->\n<div class=\"d-flex mb-4\">\n    <!-- avatar : as background -->\n    <div style=\"width:140px\" class=\"text-center\">\n        {%if item.mc_member.avatar%}\n        <div class=\"mb-1 rounded-circle d-inline-block bg-light bg-cover\"\n            style=\"width:70px; height:70px;background-image:url(\'{{item.mc_member.avatar}}\')\"></div>\n        {%else%}\n        <div style=\"width:70px; height:70px;\" class=\"mb-1 rounded-circle d-inline-block bg-light bg-cover\">\n            <i class=\"fi fi-user-male fs-1 d-block mt-1 text-gray-500\"></i>\n        </div>\n        {%endif%}\n        <span class=\"d-block text-dark\">{{item.mc_member.username}}</span>\n        <small class=\"d-block text-dark smaller\">{{helper.moment(item.createdAt).fromNow()}}</small>\n    </div>\n\n    <div class=\"w-100\">\n        <p>{{item.content|safe}}</p>\n\n        <!-- options -->\n        <ul class=\"list-inline my-3\">\n            {%if item.member_uuid === ctx.userInfo.uuid%}\n            <!-- like -->\n            <li class=\"list-inline-item\">\n\n                <!-- \n          NOTE: working ajax button! Check console for debug \n          No security implemented to block multiple votes\n          So on page refresh, should be handled by backend!\n        -->\n                <a href=\"#\" data-href=\"/cms/comments/del?id={{item.id}}&page={{ctx.query.page or 1}}\"\n                    class=\"js-ajax-confirm btn-toggle btn btn-light py-1 px-2 fs-6\" data-ajax-confirm-mode=\"ajax\"\n                    data-ajax-confirm-method=\"GET\" data-ajax-confirm-size=\"modal-md\" data-ajax-confirm-centered=\"false\"\n                    data-ajax-confirm-title=\"请确认\" data-ajax-confirm-body=\"您确定要删除该评论吗?\"\n                    data-ajax-confirm-btn-yes-class=\"btn-sm btn-primary\" data-ajax-confirm-btn-yes-text=\"确定\"\n                    data-ajax-confirm-btn-yes-icon=\"fi fi-check\" data-ajax-confirm-btn-no-class=\"btn-sm btn-light\"\n                    data-ajax-confirm-btn-no-text=\"取消\" data-ajax-confirm-btn-no-icon=\"fi fi-close\"\n                    data-ajax-confirm-callback-function=\"cms_comments_reply_callback\">\n\n                    <i class=\"fi fi-close\"></i>\n\n                    <span>删除</span>\n                </a>\n\n            </li>\n            <!-- /like -->\n            <!-- like -->\n            <li class=\"list-inline-item\">\n\n                <!-- \n          NOTE: working ajax button! Check console for debug \n          No security implemented to block multiple votes\n          So on page refresh, should be handled by backend!\n        -->\n                <a href=\"#\" class=\"js-ajax-modal btn btn-light py-1 px-2 fs-6\"\n                    data-href=\"/cms/comments/modalCommentEdit?id={{item.id}}&page={{ctx.query.page or 1}}\"\n                    data-ajax-modal-size=\"modal-md\" data-ajax-modal-centered=\"false\" data-ajax-modal-backdrop=\"static\"\n                    data-ajax-modal-callback-function=\"\">\n\n                    <i class=\"fi fi-pencil\"></i>\n\n                    <span>编辑</span>\n                </a>\n\n            </li>\n            <!-- /like -->\n            {%endif%}\n            {%if ctx.userInfo%}\n            <!-- reply -->\n            <li class=\"list-inline-item\">\n\n                <!-- \n\n          Replies are using an ajax modal!\n          Replace with wordpress style, if wordpress used!\n\n          This format can be used on custom blog CMS.\n\n        -->\n                <a href=\"#\" class=\"js-ajax-modal btn btn-light py-1 px-2 fs-6\"\n                    data-href=\"/cms/comments/modalCommentReply?id={{item.id}}&page={{ctx.query.page or 1}}\"\n                    data-ajax-modal-size=\"modal-md\" data-ajax-modal-centered=\"false\" data-ajax-modal-backdrop=\"static\"\n                    data-ajax-modal-callback-function=\"\">\n                    <i class=\"fi fi-plus\"></i>\n                    <span>回复</span>\n                </a>\n\n            </li>\n            <!-- /reply -->\n            {%endif%}\n        </ul>\n        <!-- /options -->\n\n\n        <!-- ... replies here ... -->\n\n        {%for _item in item.cms_comments_replies%}\n        <!-- REPLY -->\n        <div class=\"d-flex my-4 ms-n4\">\n\n            <!-- avatar : as background -->\n            <div style=\"width:140px\" class=\"text-center\">\n                {%if _item.mc_member.avatar%}\n                <div class=\"mb-1 rounded-circle d-inline-block bg-light bg-cover\"\n                    style=\"width:50px; height:50px;background-image:url(\'{{_item.mc_member.avatar}}\')\"></div>\n                {%else%}\n                <div style=\"width:50px; height:50px;\" class=\"mb-1 rounded-circle d-inline-block bg-light bg-cover\">\n                    <i class=\"fi fi-user-male fs-1 d-block mt-1 text-gray-500\"></i>\n                </div>\n                {%endif%}\n                <span class=\"d-block text-dark\">{{_item.mc_member.username}}</span>\n                <small class=\"d-block text-dark smaller\">{{helper.moment(_item.createdAt).fromNow()}}</small>\n            </div>\n\n            <div class=\"w-100\">\n                <p>{{_item.content|safe}}</p>\n\n                <ul class=\"list-inline my-3\">\n\n                    {%if _item.member_uuid === ctx.userInfo.uuid%}\n                    <!-- like -->\n                    <li class=\"list-inline-item\">\n\n                        <!-- \n             NOTE: working ajax button! Check console for debug \n             No security implemented to block multiple votes\n             So on page refresh, should be handled by backend!\n           -->\n                        <a href=\"#\" data-href=\"/cms/comments/replyDel?id={{_item.id}}&page={{ctx.query.page or 1}}\"\n                            class=\"js-ajax-confirm btn-toggle btn btn-light py-1 px-2 fs-6\"\n                            data-ajax-confirm-mode=\"ajax\" data-ajax-confirm-method=\"GET\"\n                            data-ajax-confirm-size=\"modal-md\" data-ajax-confirm-centered=\"false\"\n                            data-ajax-confirm-title=\"请确认\" data-ajax-confirm-body=\"您确定要删除该回复吗?\"\n                            data-ajax-confirm-btn-yes-class=\"btn-sm btn-primary\" data-ajax-confirm-btn-yes-text=\"确定\"\n                            data-ajax-confirm-btn-yes-icon=\"fi fi-check\"\n                            data-ajax-confirm-btn-no-class=\"btn-sm btn-light\" data-ajax-confirm-btn-no-text=\"取消\"\n                            data-ajax-confirm-btn-no-icon=\"fi fi-close\"\n                            data-ajax-confirm-callback-function=\"cms_comments_reply_callback\">\n\n                            <i class=\"fi fi-close\"></i>\n\n                            <span>删除</span>\n                        </a>\n\n                    </li>\n                    <!-- /like -->\n                    <!-- like -->\n                    <li class=\"list-inline-item\">\n\n                        <!-- \n             NOTE: working ajax button! Check console for debug \n             No security implemented to block multiple votes\n             So on page refresh, should be handled by backend!\n           -->\n                        <a href=\"#\" class=\"js-ajax-modal btn btn-light py-1 px-2 fs-6\"\n                            data-href=\"/cms/comments/modalCommentReplyEdit?id={{_item.id}}&page={{ctx.query.page or 1}}\"\n                            data-ajax-modal-size=\"modal-md\" data-ajax-modal-centered=\"false\"\n                            data-ajax-modal-backdrop=\"static\" data-ajax-modal-callback-function=\"\">\n\n                            <i class=\"fi fi-pencil\"></i>\n\n                            <span>编辑</span>\n                        </a>\n\n                    </li>\n                    <!-- /like -->\n                    {%endif%}\n\n                </ul>\n\n            </div>\n\n        </div>\n        <!-- /REPLY -->\n        {%endfor%}\n    </div>\n\n</div>\n<!-- /Comment 1 + Reply -->\n{%else%}\n<div class=\"alert alert-primary\" role=\"alert\">\n    暂无评论！\n</div>\n{%endfor%}\n<!-- pagination -->\n<nav aria-label=\"pagination\" class=\"mt-4\">{{pagination|safe}}</nav>\n<!-- pagination -->',1,0,'57d4337b-42ed-4e04-aba6-f3e23a7896ad'),(20,'2025-07-30 00:42:42','2025-07-30 00:42:42','37934d72-fe2c-4a0d-afbb-414993e63986','默认评论编辑模板','comment','ajax_edit','<!-- \n\n		BLOG COMMENT REPLY\n		blog-page-article-sidebar.html\n\n		MODAL : OPTIONAL\n\n	-->\n<form novalidate method=\"post\" action=\"/cms/comments/edit?page={{ctx.query.page or 1}}\" class=\"js-ajax bs-validate\"\n    data-ajax-update-url=\"false\" data-ajax-show-loading-icon=\"true\"\n    data-error-toast-text=\"<i class=\'fi fi-circle-spin fi-spin float-start\'></i> 请填写所有必填字段！\"\n    data-error-toast-delay=\"3000\" data-error-toast-position=\"top-center\" data-error-scroll-up=\"true\"\n    data-ajax-callback-function=\"cms_comments_reply_callback\">\n\n    <!-- COMMENT ID : WE ADD A REPLY TO -->\n    <input type=\"hidden\" name=\"id\" value=\"{{info.id}}\">\n    <div class=\"modal-header\">\n        <h5 class=\"modal-title m-0\">\n            编辑评论\n        </h5>\n\n        <button type=\"button\" class=\"close pointer\" data-bs-dismiss=\"modal\" aria-label=\"Close\">\n				<span class=\"fi fi-close \" aria-hidden=\"true\"></span>\n			</button>\n    </div>\n\n    <div class=\"modal-body p-3\">\n        <div class=\"clearfix\">\n\n            <div class=\"form-floating\">\n                <textarea class=\"medium-editor bg-white border p-3 rounded w-100\" required style=\"min-height:120px\" id=\"comment_description\" name=\"content\"\n          data-placeholder=\"请输入内容...\"\n          data-lng-save=\"保存\"\n          data-lng-clear=\"清空\"\n          data-lng-link=\"请输入链接地址\"\n          data-btn-picker=\"true\"\n          data-btn-bold=\"true\"\n          data-btn-italic=\"true\"\n          data-btn-underline=\"true\"\n          data-btn-link=\"true\"\n          data-btn-h1=\"false\"\n          data-btn-h2=\"false\"\n          data-btn-h3=\"false\"\n          data-btn-h4=\"true\"\n          data-btn-h5=\"true\"\n          data-btn-h6=\"true\"\n          data-btn-unordered=\"true\"\n          data-btn-ordered=\"true\">{{info.content|safe}}</textarea>\n            </div>\n        </div>\n\n    </div>\n\n    <div class=\"modal-footer\">\n\n        <button type=\"submit\" class=\"btn btn-sm btn-primary\">\n				<i class=\"fi fi-check\"></i>\n				提交评论\n			</button>\n\n        <a href=\"#\" class=\"btn btn-sm btn-secondary d-none d-sm-block\" data-bs-dismiss=\"modal\">\n            <i class=\"fi fi-close\"></i>\n            关闭\n        </a>\n\n    </div>\n\n</form>',1,0,'54cb3875-5959-4f59-9040-f160d64a8780'),(21,'2025-07-30 00:42:42','2025-07-30 00:42:42','37934d72-fe2c-4a0d-afbb-414993e63986','默认评论回复模板','comment','ajax_reply','<!-- \n\n		BLOG COMMENT REPLY\n		blog-page-article-sidebar.html\n\n		MODAL : OPTIONAL\n\n	-->\n<form novalidate method=\"post\" action=\"/cms/comments/replyAdd?page={{ctx.query.page or 1}}\" class=\"js-ajax bs-validate\"\n    data-ajax-update-url=