DROP TABLE IF EXISTS `sys_routes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_routes` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `createdAt` datetime DEFAULT NULL COMMENT '创建时间',
  `updatedAt` datetime DEFAULT NULL COMMENT '更新时间',
  `uuid` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'uuid',
  `name` varchar(255) DEFAULT NULL COMMENT '名称',
  `path` varchar(255) DEFAULT NULL COMMENT '路由 URL 路径',
  `icon` varchar(255) DEFAULT NULL COMMENT '配置菜单的图标',
  `verb` enum('head','options','get','put','post','patch','del','redirect','resources') DEFAULT 'get' COMMENT '用户触发动作，支持 get，post 等所有 HTTP 方法',
  `middleware` varchar(255) DEFAULT NULL COMMENT '在 Router 里面可以配置多个 Middleware',
  `ignoreMiddleware` varchar(255) DEFAULT NULL COMMENT '排除模块统一设置的middleware',
  `controller` varchar(255) DEFAULT NULL COMMENT '控制器',
  `action` varchar(255) DEFAULT NULL COMMENT '控制器方法',
  `admin` tinyint(1) DEFAULT '1' COMMENT '控制器/页面',
  `role` tinyint(1) DEFAULT '1' COMMENT '是否为角色权限节点',
  `class_uuid` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '关联classify的uuid',
  `puuid` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '路由父uuid',
  `sort` int DEFAULT '0' COMMENT '排序',
  `linkType` enum('schemaApi','link') DEFAULT 'schemaApi' COMMENT '链接类型',
  `link` varchar(255) DEFAULT NULL COMMENT '页面地址',
  `is_menu` tinyint(1) DEFAULT '0' COMMENT '是否是菜单',
  `app` varchar(255) DEFAULT NULL COMMENT '应用标识',
  PRIMARY KEY (`id`),
  UNIQUE KEY `sys_routes_uuid` (`uuid`),
  KEY `sys_routes_puuid` (`puuid`),
  KEY `sys_routes_app` (`app`)
) ENGINE=InnoDB AUTO_INCREMENT=150 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

